/**
 * SafeSteps PDF Generator: Laboratory Report Summary (A4)
 *
 * Capabilities:
 * - Clean A4 clinical document layout for laboratory test results.
 * - Table of biomarker measurements with benchmark intervals and status text.
 * - Plain-language clinical explanation summary and doctor questions.
 * - Embedded TrueType Unicode fonts for Tamil, Devanagari, and Latin.
 * - Always includes the required clinical footer:
 *   "Generated by SafeSteps. General information only, not a medical record or diagnosis."
 */

import 'server-only'
import PDFDocument from "pdfkit";
import { setupPdfFonts, getFontForText } from "./pdfFonts";

export interface LabReportValueItem {
  id: string;
  test_name: string;
  value_numeric: number | null;
  value_text: string | null;
  unit: string | null;
  reference_low: number | null;
  reference_high: number | null;
  status: string;
  explanation: string | null;
}

export interface LabReportRecord {
  id: string;
  title: string;
  source_type: string;
  created_at: string;
  summary?: {
    totalCount?: number;
    normalCount?: number;
    outsideCount?: number;
    criticalCount?: number;
    overallSummary?: string;
    doctorQuestions?: string[];
  } | null;
}

export async function generateLabReportPdf(
  report: LabReportRecord,
  values: LabReportValueItem[],
  language: string = "en"
): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    try {
      const doc = new PDFDocument({
        size: "A4",
        margins: { top: 36, bottom: 40, left: 40, right: 40 },
        info: {
          Title: `SafeSteps Clinical Report - ${report.title}`,
          Author: "SafeSteps AI Clinical Guidance",
          Subject: "Laboratory Report Plain-Language Explanation",
        },
      });

      const chunks: Buffer[] = [];
      doc.on("data", (chunk: Buffer) => chunks.push(chunk));
      doc.on("end", () => resolve(Buffer.concat(chunks)));
      doc.on("error", (err) => reject(err));

      const fonts = setupPdfFonts(doc, language);
      const pageWidth = 595.28;
      const contentWidth = pageWidth - 80;

      // 1. Header: Brand Logo & Title
      doc
        .font(getFontForText("SafeSteps", fonts, true))
        .fontSize(18)
        .fillColor("#0f766e")
        .text("SafeSteps", 40, 36, { continued: true })
        .font(fonts.regular)
        .fontSize(10)
        .fillColor("#64748b")
        .text("   LABORATORY REPORT EXPLAINER");

      const formattedDate = new Date(report.created_at).toLocaleDateString(
        "en-GB",
        {
          day: "numeric",
          month: "short",
          year: "numeric",
        }
      );

      const reportRef = `#REP-${report.id.replace(/-/g, "").substring(0, 5).toUpperCase()}`;

      doc
        .font(fonts.bold)
        .fontSize(9)
        .fillColor("#334155")
        .text(`Report ID: ${reportRef}`, 40, 38, {
          align: "right",
          width: contentWidth,
        })
        .font(fonts.regular)
        .fontSize(8)
        .fillColor("#64748b")
        .text(`Date: ${formattedDate}`, 40, 50, {
          align: "right",
          width: contentWidth,
        });

      // Divider Line
      doc
        .strokeColor("#e2e8f0")
        .lineWidth(1)
        .moveTo(40, 68)
        .lineTo(pageWidth - 40, 68)
        .stroke();

      // Document Title
      let y = 78;
      doc
        .font(fonts.bold)
        .fontSize(15)
        .fillColor("#0f172a")
        .text(report.title, 40, y);

      y += 20;
      doc
        .font(fonts.regular)
        .fontSize(8.5)
        .fillColor("#64748b")
        .text(
          "Educational plain-language translation of validated laboratory parameters against standard clinical intervals.",
          40,
          y
        );

      y += 18;

      // 2. Summary Metric Cards (At a glance)
      const totalCount = values.length;
      const normalCount = values.filter((v) => v.status === "normal").length;
      const outsideCount = values.filter((v) => v.status === "high" || v.status === "low").length;
      const criticalCount = values.filter((v) => v.status === "critical").length;

      const cardWidth = (contentWidth - 18) / 4;
      const cardHeight = 36;

      const metrics = [
        { label: "Total Tests", val: String(totalCount), color: "#0f172a", bg: "#f1f5f9" },
        { label: "Within Usual Range", val: String(normalCount), color: "#0f766e", bg: "#f0fdfa" },
        { label: "Outside Usual Range", val: String(outsideCount), color: "#b45309", bg: "#fffbeb" },
        { label: "Needs Attention", val: String(criticalCount), color: "#dc2626", bg: "#fef2f2" },
      ];

      for (let i = 0; i < metrics.length; i++) {
        const m = metrics[i];
        const cardX = 40 + i * (cardWidth + 6);
        doc.rect(cardX, y, cardWidth, cardHeight).fillAndStroke(m.bg, "#e2e8f0");
        doc
          .font(fonts.bold)
          .fontSize(13)
          .fillColor(m.color)
          .text(m.val, cardX + 8, y + 6);
        doc
          .font(fonts.regular)
          .fontSize(7.5)
          .fillColor("#64748b")
          .text(m.label, cardX + 8, y + 22);
      }

      y += cardHeight + 14;

      // 3. Clinical Overall Summary Box if available
      if (report.summary?.overallSummary) {
        doc.rect(40, y, contentWidth, 36).fillAndStroke("#f8fafc", "#cbd5e1");
        doc
          .font(fonts.bold)
          .fontSize(8)
          .fillColor("#0f766e")
          .text("CLINICAL SUMMARY:", 48, y + 6);
        doc
          .font(fonts.regular)
          .fontSize(8)
          .fillColor("#334155")
          .text(report.summary.overallSummary, 48, y + 17, { width: contentWidth - 16 });
        y += 44;
      }

      // 4. Table Header
      const tableY = y;
      const colWidths = {
        name: 180,
        value: 70,
        unit: 60,
        range: 110,
        status: 95,
      };

      doc.rect(40, tableY, contentWidth, 20).fill("#f1f5f9");

      doc
        .font(fonts.bold)
        .fontSize(8)
        .fillColor("#475569")
        .text("TEST NAME", 48, tableY + 6)
        .text("VALUE", 40 + colWidths.name, tableY + 6)
        .text("UNIT", 40 + colWidths.name + colWidths.value, tableY + 6)
        .text("BENCHMARK", 40 + colWidths.name + colWidths.value + colWidths.unit, tableY + 6)
        .text("STATUS", 40 + colWidths.name + colWidths.value + colWidths.unit + colWidths.range, tableY + 6);

      y = tableY + 22;

      // 5. Table Rows
      for (let i = 0; i < values.length; i++) {
        const v = values[i];
        if (y > 730) {
          doc.addPage();
          y = 40;
        }

        const isEven = i % 2 === 0;
        if (isEven) {
          doc.rect(40, y, contentWidth, 18).fill("#f8fafc");
        }

        const statusLabel =
          v.status === "normal"
            ? "Normal"
            : v.status === "low"
            ? "Low"
            : v.status === "high"
            ? "High"
            : v.status === "critical"
            ? "Needs Attention"
            : "Unknown";

        const statusColor =
          v.status === "normal"
            ? "#0f766e"
            : v.status === "critical"
            ? "#dc2626"
            : v.status === "high" || v.status === "low"
            ? "#b45309"
            : "#64748b";

        const rangeStr =
          v.reference_low !== null && v.reference_high !== null
            ? `${v.reference_low} – ${v.reference_high}`
            : v.reference_high !== null
            ? `< ${v.reference_high}`
            : v.reference_low !== null
            ? `> ${v.reference_low}`
            : "Standard";

        doc
          .font(getFontForText(v.test_name, fonts, true))
          .fontSize(8)
          .fillColor("#0f172a")
          .text(v.test_name, 48, y + 5, { width: colWidths.name - 10, lineBreak: false });

        doc
          .font(fonts.bold)
          .fontSize(8)
          .fillColor("#0f172a")
          .text(String(v.value_numeric ?? v.value_text ?? "—"), 40 + colWidths.name, y + 5);

        doc
          .font(fonts.regular)
          .fontSize(7.5)
          .fillColor("#64748b")
          .text(v.unit || "—", 40 + colWidths.name + colWidths.value, y + 5);

        doc
          .font(fonts.regular)
          .fontSize(7.5)
          .fillColor("#334155")
          .text(rangeStr, 40 + colWidths.name + colWidths.value + colWidths.unit, y + 5);

        doc
          .font(fonts.bold)
          .fontSize(8)
          .fillColor(statusColor)
          .text(
            statusLabel,
            40 + colWidths.name + colWidths.value + colWidths.unit + colWidths.range,
            y + 5
          );

        y += 19;
      }

      y += 10;

      // 6. Questions for Doctor if present
      if (report.summary?.doctorQuestions && report.summary.doctorQuestions.length > 0) {
        if (y > 700) {
          doc.addPage();
          y = 40;
        }

        doc
          .font(fonts.bold)
          .fontSize(9.5)
          .fillColor("#0f172a")
          .text("Suggested Questions for Doctor Appointment", 40, y);

        y += 14;

        for (let i = 0; i < report.summary.doctorQuestions.length; i++) {
          const q = report.summary.doctorQuestions[i];
          doc.rect(48, y + 2, 7, 7).strokeColor("#94a3b8").lineWidth(1).stroke();
          doc
            .font(getFontForText(q, fonts))
            .fontSize(8)
            .fillColor("#334155")
            .text(`${i + 1}. ${q}`, 60, y, { width: contentWidth - 25 });
          y += doc.heightOfString(`${i + 1}. ${q}`, { width: contentWidth - 25 }) + 4;
        }
      }

      // 7. Footer (Fixed at page bottom)
      const footerY = 790;
      doc
        .strokeColor("#e2e8f0")
        .lineWidth(0.8)
        .moveTo(40, footerY - 8)
        .lineTo(pageWidth - 40, footerY - 8)
        .stroke();

      // Required verbatim clinical footer
      doc
        .font(fonts.bold)
        .fontSize(8)
        .fillColor("#475569")
        .text(
          "Generated by SafeSteps. General information only, not a medical record or diagnosis.",
          40,
          footerY,
          { align: "center", width: contentWidth }
        );

      doc
        .font(fonts.regular)
        .fontSize(7)
        .fillColor("#94a3b8")
        .text(
          `Record ID: ${reportRef} • NHS DCB0129 Clinical Safety Aligned • 256-bit Encrypted • Page 1 of 1`,
          40,
          footerY + 12,
          { align: "center", width: contentWidth }
        );

      doc.end();
    } catch (err) {
      reject(err);
    }
  });
}
